<?php
/** Independent list cover; the existing featured-image attachment remains the clue. */
defined('ABSPATH') || exit;
function tkcq_card_image($id){$cover=(int)get_post_meta($id,'_tkcq_cover_id',true);$url=$cover&&wp_attachment_is_image($cover)?wp_get_attachment_image_url($cover,'large'):false;return $url?:plugins_url('city-surprise-cover.svg',__FILE__);}
add_action('add_meta_boxes_tkc_quest',function(){add_meta_box('tkcq-cover','Featured picture / 封面图',function($post){$id=(int)get_post_meta($post->ID,'_tkcq_cover_id',true);$image=$id?wp_get_attachment_image_url($id,'medium'):false;wp_nonce_field('tkcq_cover','tkcq_cover_nonce');echo '<div class="tkcq-cover-control"><input type="hidden" name="tkcq_cover_id" value="'.absint($id).'"><p><img class="tkcq-cover-preview" src="'.esc_url($image?:plugins_url('city-surprise-cover.svg',__FILE__)).'" style="width:100%;height:auto" alt="Cover preview"></p><p><button type="button" class="button tkcq-cover-choose">Choose cover / 选择封面图</button></p><p><button type="button" class="button-link tkcq-cover-remove">Remove cover / 移除封面图</button></p><p>Shown on Home and Activities. The Clue image below is only shown inside the round. Without a cover, a general illustration is used. 封面用于首页和活动列表；线索图只在详情页显示。未设置封面时使用通用插画。</p></div>';},'tkc_quest','side','high');});
add_action('admin_enqueue_scripts',function($hook){$screen=get_current_screen();if(!$screen||$screen->post_type!=='tkc_quest'||!in_array($hook,['post.php','post-new.php'],true))return;wp_enqueue_media();wp_enqueue_script('tkcq-cover-admin',plugins_url('city-surprise-cover.js',__FILE__),['media-editor'],'1.7.3',true);wp_localize_script('tkcq-cover-admin','tkcqCover',['placeholder'=>plugins_url('city-surprise-cover.svg',__FILE__)]);});
add_action('save_post_tkc_quest',function($id){if(wp_is_post_revision($id)||wp_is_post_autosave($id)||!current_user_can('edit_post',$id)||empty($_POST['tkcq_cover_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['tkcq_cover_nonce'])),'tkcq_cover'))return;$cover=absint($_POST['tkcq_cover_id']??0);if($cover&&!wp_attachment_is_image($cover))return;if($cover)update_post_meta($id,'_tkcq_cover_id',$cover);else delete_post_meta($id,'_tkcq_cover_id');},15);
